        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        if (!IsConfigured)
        {
            return $"[Web search for \"{query}\"]: Live search is not configured. " +
                   "Set GOOGLE_API_KEY and GOOGLE_SEARCH_ENGINE_ID environment variables to enable live results. " +
                   "Proceeding with general knowledge only.";
        }

        var url = $"https://www.googleapis.com/customsearch/v1?key={_apiKey}&cx={_searchEngineId}&q={Uri.EscapeDataString(query)}&num={maxResults}";

        try
        {
            var response = await _http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(response);

            if (!doc.RootElement.TryGetProperty("items", out var items))
                return $"No results found for \"{query}\".";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for \"{query}\":");
            sb.AppendLine();

            int index = 1;
            foreach (var item in items.EnumerateArray())
            {
                var title = item.GetProperty("title").GetString();
                var snippet = item.TryGetProperty("snippet", out var s) ? s.GetString() : "No snippet";
                var link = item.GetProperty("link").GetString();

                sb.AppendLine($"{index}. {title}");
                sb.AppendLine($"   {snippet}");
                sb.AppendLine($"   URL: {link}");
                sb.AppendLine();
                index++;
            }

            return sb.ToString();
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }
}

/// <summary>
/// Provides note-taking capabilities for the research agent.
/// The agent uses this to collect and organize findings during research.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<ResearchNote> _notes = [];

    public IReadOnlyList<ResearchNote> Notes => _notes;

    [Description("Save a research note with a title and content. Use this to record key findings from search results.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The content/body of the note")] string content,
        [Description("The source URL or reference, if any")] string? source = null)
    {
        var note = new ResearchNote
        {
            Id = _notes.Count + 1,
            Title = title,
            Content = content,
            Source = source,
            Timestamp = DateTimeOffset.UtcNow,
        };
        _notes.Add(note);
        return $"Note #{note.Id} saved: \"{title}\"";
    }

    [Description("Retrieve all saved research notes. Use this to review collected findings before writing a summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===");
        sb.AppendLine();

        foreach (var note in _notes)
        {
            sb.AppendLine($"--- Note #{note.Id}: {note.Title} ---");
            sb.AppendLine(note.Content);
            if (!string.IsNullOrEmpty(note.Source))
                sb.AppendLine($"Source: {note.Source}");
            sb.AppendLine();
        }

        return sb.ToString();
    }

    [Description("Delete a specific note by its ID number.")]
    public string DeleteNote([Description("The ID number of the note to delete")] int noteId)
    {
        var note = _notes.Find(n => n.Id == noteId);
        if (note is null)
            return $"Note #{noteId} not found.";

        _notes.Remove(note);
        return $"Note #{noteId} (\"{note.Title}\") deleted.";
    }
}

public sealed class ResearchNote
{
    public int Id { get; init; }
    public required string Title { get; init; }
    public required string Content { get; init; }
    public string? Source { get; init; }
    public DateTimeOffset Timestamp { get; init; }
}

