using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this app.");

const string modelId = "gpt-4o-mini-2024-07-18";

var googleApiKey = Environment.GetEnvironmentVariable("GOOGLE_API_KEY");
var googleSearchEngineId = Environment.GetEnvironmentVariable("GOOGLE_SEARCH_ENGINE_ID");

// --- Build tools ---
using var httpClient = new HttpClient();
var searchTool = new WebSearchTool(httpClient, googleApiKey, googleSearchEngineId);
var noteTool = new NoteTakingTool();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(searchTool.SearchWebAsync),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetAllNotes),
    AIFunctionFactory.Create(noteTool.DeleteNote),
};

// --- Build the chat client via MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Build the agent using Microsoft Agent Framework ---
var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    instructions: """
        You are a thorough research assistant. When given a topic to research:

        1. Break the topic into 2-3 specific search queries.
        2. Use the SearchWebAsync tool to search for each query.
        3. Use the SaveNote tool to record the most important findings from each search,
           including titles, key facts, and source URLs.
        4. After gathering notes, use GetAllNotes to review your collected research.
        5. Finally, write a comprehensive summary that synthesizes all findings.

        Always cite your sources. Be factual and objective.
        If web search is not available, state that clearly and provide what
        you can from general knowledge, noting the limitation.
        """,
    tools: tools);

// --- Configure run options with guardrails ---
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

// --- Interactive loop ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (MAF + MEAI)     ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
if (!searchTool.IsConfigured)
{
    Console.WriteLine("║                                          ║");
    Console.WriteLine("║  ⚠ Web search not configured.            ║");
    Console.WriteLine("║  Set GOOGLE_API_KEY and                   ║");
    Console.WriteLine("║  GOOGLE_SEARCH_ENGINE_ID for live search. ║");
}
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Research topic> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic))
        continue;

    if (topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.WriteLine($"🔍 Researching: {topic}");
    Console.WriteLine(new string('─', 50));

    try
    {
        var session = await agent.CreateSessionAsync();

        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic and provide a comprehensive summary: {topic}",
            session,
            runOptions))
        {
            Console.Write(update.Text);
        }

        Console.WriteLine();
        Console.WriteLine(new string('─', 50));

        // Show collected notes
        if (noteTool.Notes.Count > 0)
        {
            Console.WriteLine($"\n📝 Notes collected: {noteTool.Notes.Count}");
            foreach (var note in noteTool.Notes)
            {
                Console.WriteLine($"   • {note.Title}" +
                    (note.Source is not null ? $" (Source: {note.Source})" : ""));
            }
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}");
    }

    Console.WriteLine();
}

